/**
 * Physically removes issues with their label links, comments and attachments,
 * remembering each project's highest number so it is never reused.
 */
export async function purgeIssues(
  orgId: OrgId,
  expired: readonly Issue[],
): Promise<PurgedIssues> {
  const commentIds: string[] = [];
  let attachmentMb = 0;
  if (expired.length === 0) return { commentIds, attachmentMb };

  const db = getDb();
  db.transaction((tx) => {
    const ids = expired.map((issue) => issue.id as string);
    for (let i = 0; i < ids.length; i += 500) {
      const chunk = ids.slice(i, i + 500);
      const inIssues = (col: typeof comments.issueId) =>
        and(orgPredicate(col.table === undefined ? comments.orgId : comments.orgId, orgId), inArray(col, chunk));
      void inIssues;

      const commentRows = tx
        .select({ id: comments.id })
        .from(comments)
        .where(
          and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, chunk)),
        )
        .all();
      commentIds.push(...commentRows.map((row) => row.id));

      const attachmentRows = tx
        .select({ sizeBytes: attachments.sizeBytes })
        .from(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, chunk),
          ),
        )
        .all();
      for (const row of attachmentRows) {
        attachmentMb += Math.ceil(row.sizeBytes / (1024 * 1024));
      }

      tx.delete(comments)
        .where(
          and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, chunk)),
        )
        .run();
      tx.delete(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, chunk),
          ),
        )
        .run();
      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            inArray(issueLabels.issueId, chunk),
          ),
        )
        .run();
      tx.delete(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, chunk)))
        .run();
    }

    const highest = new Map<string, number>();
    for (const issue of expired) {
      highest.set(
        issue.projectId,
        Math.max(highest.get(issue.projectId) ?? 0, issue.number),
      );
    }
    for (const [projectId, number] of highest) {
      tx.update(projects)
        .set({
          issueCounter: sql`max(${projects.issueCounter}, ${number})`,
        })
        .where(
          and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)),
        )
        .run();
    }
  });

  return { commentIds, attachmentMb };
}

