  );
  assertCan(actor, "issue:archive", issueResource(issue));

  if (!isArchived(issue) || issue.archivedAt === null) {
    throw new RestoreRefusedError("not_archived", issue.id);
  }

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const lifetime = getPlanLimits(org.plan).retentionDays * MS_PER_DAY;
  if (Date.now() - new Date(issue.archivedAt).getTime() >= lifetime) {
